reducedMotion:
@media print, (prefers-reduced-motion: reduce) {
  .animate__animated { animation-duration: 1ms !important; transition-duration: 1ms !important; animation-iteration-count: 1 !important; animation-delay: 1ms !important; transition-delay: 1ms !important; }
  .animate__animated[class*="Out"] { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .fa-beat, .fa-bounce, .fa-fade, .fa-beat-fade, .fa-flip, .fa-pulse, .fa-shake, .fa-spin, .c-btn--has-spinner::before, .fa-spin-pulse { animation-delay: -1ms; animation-duration: 1ms; animation-iteration-count: 1; transition-delay: 0s; transition-duration: 0s; }
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; animation-delay: 1ms !important; transition-delay: 1ms !important; scroll-behavior: auto !important; }
}
